public class StringPoolDemo {
    public static void main(String[] args) {
        String s1 = "hello";           // creates "hello" in pool
        String s2 = "hello";           // reuses existing "hello" from pool
        String s3 = new String("hello"); // creates new object on heap

        System.out.println(s1 == s2);  // true - same pool reference
        System.out.println(s1 == s3);  // false - different objects
        System.out.println(s1.equals(s3)); // true - same content

        // Compile-time concatenation uses pool
        String s4 = "hel" + "lo";      // compiler combines to "hello" literal
        System.out.println(s1 == s4);  // true - pool reuse

        // Runtime concatenation doesn't use pool
        String part = "hel";
        String s5 = part + "lo";       // runtime operation, new object
        System.out.println(s1 == s5);  // false - not from pool
    }
}

public class LiteralVsNew {
    public static void main(String[] args) {
        String a = "hello";              // goes into the String pool
        String b = "hello";              // reuses the SAME pooled object
        String c = new String("hello");  // forces a NEW heap object, not pooled

        System.out.println(a == b);        // true  (same pooled reference)
        System.out.println(a == c);        // false (different objects)
        System.out.println(a.equals(c));   // true  (same characters)

        String d = c.intern();             // returns the pooled "hello"
        System.out.println(a == d);        // true
    }
}

import java.io.*;
import java.util.*;

public class InternDemo {
    public static void main(String[] args) throws IOException {
        // Without intern: creates new String for each row
        List<String> statusesNoIntern = new ArrayList<>();
        for (int i = 0; i < 10000; i++) {
            String status = new String("ACTIVE"); // 10,000 objects
            statusesNoIntern.add(status);
        }

        // With intern: reuses pooled object
        List<String> statusesWithIntern = new ArrayList<>();
        for (int i = 0; i < 10000; i++) {
            String status = new String("ACTIVE").intern(); // 1 object
            statusesWithIntern.add(status);
        }

        // All references point to same pooled object
        String s1 = statusesWithIntern.get(0);
        String s2 = statusesWithIntern.get(9999);
        System.out.println(s1 == s2); // true - same pooled reference

        // Practical use: parsing CSV
        var userStatuses = parseCsvColumn("users.csv", "status");
        System.out.println("Unique objects: " + countUniqueObjects(userStatuses));
    }

    static List<String> parseCsvColumn(String file, String column) {
        return List.of(); // simplified
    }

    static int countUniqueObjects(List<String> list) {
        return (int) list.stream().distinct().count();
    }
}

public class PoolGarbageCollectionDemo {
    public static void main(String[] args) {
        // Create and intern a large string
        String large = generateLargeString().intern(); // added to pool
        System.out.println("String interned: " + large.length() + " chars");

        // At this point, 'large' references the pooled string
        // The pool contains this string and it's reachable

        large = null; // remove the only reference

        // Now the pooled string is unreachable
        // In Java 7+: eligible for garbage collection
        // In Java 6: would stay in PermGen forever

        System.gc(); // suggest garbage collection
        System.out.println("GC suggested, pooled string may be collected");

        // Demonstrating with literals
        if (someRareCondition()) {
            String temp = "RARE_STATUS".intern();
            processStatus(temp);
        } // temp goes out of scope here

        // If no other code references "RARE_STATUS", it can be GC'd in Java 7+
    }

    static String generateLargeString() {
        return "x".repeat(1_000_000); // 1MB string
    }

    static boolean someRareCondition() { return Math.random() > 0.5; }
    static void processStatus(String s) { }
}

public class StringConcatenationDemo {
    public static void main(String[] args) {
        // Single statement: compiler optimizes to StringBuilder
        String s1 = "Hello" + " " + "World" + "!"; // efficient

        // Multiple statements: compiler optimizes each separately
        String s2 = "Hello";
        s2 = s2 + " World";  // new StringBuilder per statement
        s2 = s2 + "!";       // another new StringBuilder

        // Loop: INEFFICIENT - new StringBuilder each iteration
        String result = "";
        for (int i = 0; i < 1000; i++) {
            result = result + i + ","; // 1000 StringBuilders created
        }

        // Loop: EFFICIENT - manual StringBuilder reused
        var builder = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            builder.append(i).append(","); // same builder throughout
        }
        String efficient = builder.toString();

        // Practical example: building CSV from database results
        var csv = buildCsv(fetchOrders());
        System.out.println(csv);
    }

    static String buildCsv(List<Order> orders) {
        var csv = new StringBuilder();
        for (var order : orders) {
            csv.append(order.id()).append(",").append(order.total()).append("\n");
        }
        return csv.toString();
    }

    static List<Order> fetchOrders() { return List.of(); }
}

record Order(Long id, double total) {}
